diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index 3529c0fd..2fab51c2 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1596,6 +1596,7 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {

   if (parser->m_parentParser)
     return XML_FALSE;
+  FREE(parser, parser->m_unknownEncodingMem);
   /* move m_tagStack to m_freeTagList */
   tStk = parser->m_tagStack;
   while (tStk) {
@@ -1615,7 +1616,6 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {
    * entities) */
   moveEntityList(&parser->m_freeEntities, &parser->m_openValueEntities);
   moveToFreeBindingList(parser, parser->m_inheritedBindings);
-  FREE(parser, parser->m_unknownEncodingMem);
   if (parser->m_unknownEncodingRelease)
     callUnknownEncodingRelease(parser);
   poolClear(&parser->m_tempPool);
@@ -1624,6 +1624,10 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {
   parser->m_protocolEncodingName = NULL;
   parserInit(parser, encodingName);
   dtdReset(parser->m_dtd, parser);
+  if (encodingName && ! parser->m_protocolEncodingName) {
+    parser->m_errorCode = XML_ERROR_NO_MEMORY;
+    return XML_FALSE;
+  }
   return XML_TRUE;
 }

diff --git a/expat/tests/alloc_tests.c b/expat/tests/alloc_tests.c
index c7939708..1c4c6e75 100644
--- a/expat/tests/alloc_tests.c
+++ b/expat/tests/alloc_tests.c
@@ -563,6 +563,23 @@ START_TEST(test_alloc_explicit_encoding) {
 }
 END_TEST

+/* Test robustness of XML_ParserReset() with a failing allocator when setting encoding */
+START_TEST(test_alloc_reset_encoding) {
+  int i;
+  const int max_alloc_count = 5;
+
+  for (i = 0; i < max_alloc_count; i++) {
+    g_allocation_count = i;
+    if (XML_ParserReset(g_parser, XCS("us-ascii")) == XML_TRUE)
+      break;
+  }
+  if (i == 0)
+    fail("Reset with encoding succeeded despite failing allocator");
+  else if (i == max_alloc_count)
+    fail("Reset with encoding failed at max allocation count");
+}
+END_TEST
+
 /* Test robustness of XML_SetBase against a failing allocator */
 START_TEST(test_alloc_set_base) {
   const XML_Char *new_base = XCS("/local/file/name.xml");
@@ -2336,6 +2353,7 @@ make_alloc_test_case(Suite *s) {
   tcase_add_test__ifdef_xml_dtd(tc_alloc, test_alloc_parameter_entity);
   tcase_add_test__ifdef_xml_dtd(tc_alloc, test_alloc_dtd_default_handling);
   tcase_add_test(tc_alloc, test_alloc_explicit_encoding);
+  tcase_add_test(tc_alloc, test_alloc_reset_encoding);
   tcase_add_test(tc_alloc, test_alloc_set_base);
   tcase_add_test(tc_alloc, test_alloc_realloc_buffer);
   tcase_add_test__if_xml_ge(tc_alloc, test_alloc_ext_entity_realloc_buffer);

diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index 9dcc42da..06182d86 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -1598,9 +1598,9 @@ XML_ParserReset(XML_Parser parser, const XML_Char *encodingName) {
   /* move m_openValueEntities to m_freeEntities (i.e. same task but for value
    * entities) */
   moveEntityList(&parser->m_freeEntities, &parser->m_openValueEntities);
-  moveToFreeBindingList(parser, parser->m_inheritedBindings);
   if (parser->m_unknownEncodingRelease)
     callUnknownEncodingRelease(parser);
+  moveToFreeBindingList(parser, parser->m_inheritedBindings);
   poolClear(&parser->m_tempPool);
   poolClear(&parser->m_temp2Pool);
   FREE(parser, (void *)parser->m_protocolEncodingName);
@@ -1843,6 +1843,10 @@ XML_ParserFree(XML_Parser parser) {
   TAG *tagList;
   if ((parser == NULL) || isCalledFromInsideHandler(parser))
     return;
+  // The application-defined release callback may access the parser, so it
+  // must run before any parser state is freed.
+  if (parser->m_unknownEncodingRelease)
+    callUnknownEncodingRelease(parser);
   /* free m_tagStack and m_freeTagList */
   tagList = parser->m_tagStack;
   for (;;) {
@@ -1911,8 +1915,6 @@ XML_ParserFree(XML_Parser parser) {
   FREE(parser, parser->m_dataBuf);
   FREE(parser, parser->m_nsAtts);
   FREE(parser, parser->m_unknownEncodingMem);
-  if (parser->m_unknownEncodingRelease)
-    callUnknownEncodingRelease(parser);
   FREE(parser, parser);
 }
